parameters.query:
SELECT json_build_object(
  'h_lancamentos', (SELECT ROUND(EXTRACT(EPOCH FROM (NOW()-MAX(criado_em)))/3600,1) FROM financas_lancamentos),
  'h_investimentos', (SELECT ROUND(EXTRACT(EPOCH FROM (NOW()-MAX(atualizado_em)))/3600,1) FROM financas_investimentos),
  'h_faturas', (SELECT ROUND(EXTRACT(EPOCH FROM (NOW()-MAX(atualizado_em)))/3600,1) FROM financas_faturas),
  'ultimo_lancamento', (SELECT TO_CHAR(MAX(data_lancamento),'DD/MM/YYYY') FROM financas_lancamentos WHERE status_pluggy='POSTED')
) AS saude;

parameters.jsCode:
const s = $json.saude || {};
const LIM = 36;
const probs = [];
if ((s.h_faturas ?? 999) > LIM) probs.push(`• Faturas: sem atualizar há ${s.h_faturas}h`);
if ((s.h_investimentos ?? 999) > LIM) probs.push(`• Investimentos: sem atualizar há ${s.h_investimentos}h`);
if ((s.h_lancamentos ?? 999) > 72) probs.push(`• Lançamentos: nada novo há ${s.h_lancamentos}h (pode ser normal se sem gastos)`);
if (!probs.length) return [];
const texto = `⚠️ *Alerta de sincronização*\n\nAlgo pode ter parado de atualizar:\n${probs.join('\n')}\n\nÚltimo lançamento: ${s.ultimo_lancamento || '—'}`;
return [{ json: { text: texto } }];
